import{_ as o,o as r,c as t,a0 as n}from"./chunks/framework.DNNiP2TX.js";const p=JSON.parse('{"title":"@shutter-network/concorde/scheduler routes","description":"","frontmatter":{"title":"@shutter-network/concorde/scheduler routes"},"headers":[],"relativePath":"reference/routes/scheduler.md","filePath":"reference/routes/scheduler.md"}'),d={name:"reference/routes/scheduler.md"};function s(i,e,c,a,l,u){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="shutter-network-concorde-scheduler" tabindex="-1">@shutter-network/concorde/scheduler <a class="header-anchor" href="#shutter-network-concorde-scheduler" aria-label="Permalink to &quot;@shutter-network/concorde/scheduler&quot;">​</a></h1><p>The HTTP routes this component serves: 4 on the Agent server.</p><p><strong>Every path is relative.</strong> Each one is printed as the plugin declares it, under whatever prefix the component&#39;s constructor registers that plugin at. This page states no mount point, because the constructor is where the mount point is decided.</p><p>Generated from what the route plugins in <code>src/scheduler/routes.ts</code> declare, which is what a running Gateway serves at <code>GET /openapi.json</code>. Never edited by hand.</p><h2 id="agent-server" tabindex="-1">Agent server <a class="header-anchor" href="#agent-server" aria-label="Permalink to &quot;Agent server&quot;">​</a></h2><p><strong>The Agent server has no authentication of any kind.</strong> Everything below is reachable by the agent, and therefore by an injected prompt (<a href="https://github.com/shutter-network/concorde/blob/main/docs/adr/0003-prompt-injection-is-an-accepted-risk.md" target="_blank" rel="noreferrer">ADR-0003</a>). Nothing on it names a credential.</p><h3 id="get-schedules" tabindex="-1"><code>GET /schedules</code> <a class="header-anchor" href="#get-schedules" aria-label="Permalink to &quot;`GET /schedules`&quot;">​</a></h3><p><strong>List Schedules, soonest to fire first</strong></p><p>Every live Schedule, ascending by <code>nextFireAt</code> so the next to fire is first. <code>name</code> breaks a tie. A spent or cancelled Schedule is absent, because the row <em>is</em> the arming. <code>limit</code> defaults to 50 and is capped at 200. A larger value is <strong>refused with a 400</strong> rather than quietly reduced. There is no cursor and no offset. The Schedules past the cap are reachable only by raising the limit or narrowing the arrangement. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Schedules</code>.</p><p><strong>Query parameters</strong></p><ul><li><strong><code>limit</code></strong> <code>integer</code>, optional, 1 to 200, default <code>50</code></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The live Schedules, soonest fire first.</p><ul><li><strong><code>schedules</code></strong> array of <code>object</code>, required <ul><li><p><strong><code>name</code></strong> <code>string</code>, required</p></li><li><p><strong><code>spec</code></strong> one of 2 shapes, required</p><ul><li><strong>Option 1:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;once&quot;</code></li><li><strong><code>at</code></strong> <code>string</code>, required</li></ul></li><li><strong>Option 2:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;cron&quot;</code></li><li><strong><code>expr</code></strong> <code>string</code>, required</li><li><strong><code>tz</code></strong> <code>string</code>, required</li></ul></li></ul></li><li><p><strong><code>data</code></strong> any JSON, required</p><p>Arbitrary JSON, echoed verbatim in the fired Signal&#39;s payload. The Scheduler never interprets it, so what a Schedule carries is the creator&#39;s convention and their Signal Handler is where it is read. Omitted, it is stored as null.</p></li><li><p><strong><code>until</code></strong> <code>string</code> or null, required</p><p>The cron end instant if the Schedule has one, else null. Always null for a once.</p></li><li><p><strong><code>nextFireAt</code></strong> <code>string</code>, required</p><p>When the Schedule next fires, ISO 8601. Always present: reads answer only live Schedules, and a create that would resolve to no future fire is a 400 rather than a spent record.</p></li></ul></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The <code>limit</code> is out of range or not an integer, or a parameter this route does not take was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="delete-schedules-name" tabindex="-1"><code>DELETE /schedules/{name}</code> <a class="header-anchor" href="#delete-schedules-name" aria-label="Permalink to &quot;`DELETE /schedules/{name}`&quot;">​</a></h3><p><strong>Cancel a Schedule by name</strong></p><p>Cancel the Schedule this <code>name</code> addresses, and stop every future fire. <strong>204</strong> on success, and <strong>404</strong> on a name that addresses none. An unknown name is refused rather than answered an idempotent 204. So a caller learns a Schedule was already gone rather than being told it stopped nothing. This route takes no query parameters at all. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Schedules</code>.</p><p><strong>Path parameters</strong></p><ul><li><strong><code>name</code></strong> <code>string</code>, required, matching <code>^[A-Za-z0-9._-]{1,128}$</code></li></ul><p><strong>Responses</strong></p><p><strong><code>204</code></strong> with no body</p><p>The Schedule was cancelled; every future fire is stopped.</p><p><strong><code>400</code></strong> <code>application/json</code></p><p>The name in the path is not a legible url-safe key of up to 128 letters, digits, dots, dashes or underscores, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>404</code></strong> <code>application/json</code></p><p>No live Schedule has that name to cancel.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="get-schedules-name" tabindex="-1"><code>GET /schedules/{name}</code> <a class="header-anchor" href="#get-schedules-name" aria-label="Permalink to &quot;`GET /schedules/{name}`&quot;">​</a></h3><p><strong>Read one Schedule by name</strong></p><p>The live Schedule this <code>name</code> addresses, or a 404 when none does. A Schedule that fired out or was cancelled is gone, so this answers only what is still arranged. This route takes no query parameters at all. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Schedules</code>.</p><p><strong>Path parameters</strong></p><ul><li><strong><code>name</code></strong> <code>string</code>, required, matching <code>^[A-Za-z0-9._-]{1,128}$</code></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The Schedule.</p><ul><li><p><strong><code>name</code></strong> <code>string</code>, required</p></li><li><p><strong><code>spec</code></strong> one of 2 shapes, required</p><ul><li><strong>Option 1:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;once&quot;</code></li><li><strong><code>at</code></strong> <code>string</code>, required</li></ul></li><li><strong>Option 2:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;cron&quot;</code></li><li><strong><code>expr</code></strong> <code>string</code>, required</li><li><strong><code>tz</code></strong> <code>string</code>, required</li></ul></li></ul></li><li><p><strong><code>data</code></strong> any JSON, required</p><p>Arbitrary JSON, echoed verbatim in the fired Signal&#39;s payload. The Scheduler never interprets it, so what a Schedule carries is the creator&#39;s convention and their Signal Handler is where it is read. Omitted, it is stored as null.</p></li><li><p><strong><code>until</code></strong> <code>string</code> or null, required</p><p>The cron end instant if the Schedule has one, else null. Always null for a once.</p></li><li><p><strong><code>nextFireAt</code></strong> <code>string</code>, required</p><p>When the Schedule next fires, ISO 8601. Always present: reads answer only live Schedules, and a create that would resolve to no future fire is a 400 rather than a spent record.</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The name in the path is not a legible url-safe key of up to 128 letters, digits, dots, dashes or underscores, or a query parameter was written.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><p><strong><code>404</code></strong> <code>application/json</code></p><p>No live Schedule has that name.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul><h3 id="put-schedules-name" tabindex="-1"><code>PUT /schedules/{name}</code> <a class="header-anchor" href="#put-schedules-name" aria-label="Permalink to &quot;`PUT /schedules/{name}`&quot;">​</a></h3><p><strong>Create or update a Schedule by name</strong></p><p>Create-or-update the Schedule this <code>name</code> addresses. An upsert, so a retry or a revised plan converges to one Schedule rather than a duplicate. Answers <strong>201</strong> when the name was new and <strong>200</strong> when it already existed, each with the resulting read model. There is no 404, since a <code>PUT</code> on an absent name creates it. The <code>name</code> is the sole identifier and comes from the path.</p><p>A create that could never fire is a <strong>400</strong> rather than a stored Schedule that never fires. That covers a <code>once</code> already past, and a cron whose <code>until</code> sits at or before its next occurrence. This route takes no query parameters at all. An unknown query parameter is a <strong>400</strong>, not a filter that did nothing and a request answered with everything.</p><p>Tagged <code>Schedules</code>.</p><p><strong>Path parameters</strong></p><ul><li><strong><code>name</code></strong> <code>string</code>, required, matching <code>^[A-Za-z0-9._-]{1,128}$</code></li></ul><p><strong>Request body</strong></p><p><code>application/json</code>, required.</p><ul><li><p><strong><code>spec</code></strong> one of 2 shapes, required</p><ul><li><p><strong>Option 1:</strong> <code>object</code></p><ul><li><p><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;once&quot;</code></p></li><li><p><strong><code>at</code></strong> <code>string</code>, required</p><p>The single absolute instant to fire at, ISO 8601. Refused as a 400 if malformed or already past.</p></li></ul></li><li><p><strong>Option 2:</strong> <code>object</code></p><ul><li><p><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;cron&quot;</code></p></li><li><p><strong><code>expr</code></strong> <code>string</code>, required</p><p>A cron expression, parsed by cron-parser. A malformed one is a 400.</p></li><li><p><strong><code>tz</code></strong> <code>string</code>, optional</p><p>The IANA time zone the expression is evaluated in. Omitted, it is UTC. An unknown zone is a 400.</p></li></ul></li></ul></li><li><p><strong><code>data</code></strong> any JSON, optional</p><p>Arbitrary JSON, echoed verbatim in the fired Signal&#39;s payload. The Scheduler never interprets it, so what a Schedule carries is the creator&#39;s convention and their Signal Handler is where it is read. Omitted, it is stored as null.</p></li><li><p><strong><code>until</code></strong> <code>string</code>, optional</p><p>A cron Schedule&#39;s optional end instant, ISO 8601: after its last occurrence at or before this, the Schedule is retired. Meaningless for a once, which bounds itself by firing once, so a once carrying one is a 400.</p></li></ul><p><strong>Responses</strong></p><p><strong><code>200</code></strong> <code>application/json</code></p><p>The Schedule as it now stands, updated.</p><ul><li><p><strong><code>name</code></strong> <code>string</code>, required</p></li><li><p><strong><code>spec</code></strong> one of 2 shapes, required</p><ul><li><strong>Option 1:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;once&quot;</code></li><li><strong><code>at</code></strong> <code>string</code>, required</li></ul></li><li><strong>Option 2:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;cron&quot;</code></li><li><strong><code>expr</code></strong> <code>string</code>, required</li><li><strong><code>tz</code></strong> <code>string</code>, required</li></ul></li></ul></li><li><p><strong><code>data</code></strong> any JSON, required</p><p>Arbitrary JSON, echoed verbatim in the fired Signal&#39;s payload. The Scheduler never interprets it, so what a Schedule carries is the creator&#39;s convention and their Signal Handler is where it is read. Omitted, it is stored as null.</p></li><li><p><strong><code>until</code></strong> <code>string</code> or null, required</p><p>The cron end instant if the Schedule has one, else null. Always null for a once.</p></li><li><p><strong><code>nextFireAt</code></strong> <code>string</code>, required</p><p>When the Schedule next fires, ISO 8601. Always present: reads answer only live Schedules, and a create that would resolve to no future fire is a 400 rather than a spent record.</p></li></ul><p><strong><code>201</code></strong> <code>application/json</code></p><p>The Schedule as created.</p><ul><li><p><strong><code>name</code></strong> <code>string</code>, required</p></li><li><p><strong><code>spec</code></strong> one of 2 shapes, required</p><ul><li><strong>Option 1:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;once&quot;</code></li><li><strong><code>at</code></strong> <code>string</code>, required</li></ul></li><li><strong>Option 2:</strong> <code>object</code><ul><li><strong><code>kind</code></strong> <code>string</code>, required, always <code>&quot;cron&quot;</code></li><li><strong><code>expr</code></strong> <code>string</code>, required</li><li><strong><code>tz</code></strong> <code>string</code>, required</li></ul></li></ul></li><li><p><strong><code>data</code></strong> any JSON, required</p><p>Arbitrary JSON, echoed verbatim in the fired Signal&#39;s payload. The Scheduler never interprets it, so what a Schedule carries is the creator&#39;s convention and their Signal Handler is where it is read. Omitted, it is stored as null.</p></li><li><p><strong><code>until</code></strong> <code>string</code> or null, required</p><p>The cron end instant if the Schedule has one, else null. Always null for a once.</p></li><li><p><strong><code>nextFireAt</code></strong> <code>string</code>, required</p><p>When the Schedule next fires, ISO 8601. Always present: reads answer only live Schedules, and a create that would resolve to no future fire is a 400 rather than a spent record.</p></li></ul><p><strong><code>400</code></strong> <code>application/json</code></p><p>The path <code>name</code> is malformed, a query parameter was written, an unknown field or an unknown <code>kind</code> was sent, a <code>once</code> carried a cron-only <code>until</code>, the cron <code>expr</code> is invalid or its <code>tz</code> unknown, or the <code>at</code>/<code>until</code> is malformed or the <code>once</code> instant already past.</p><ul><li><strong><code>statusCode</code></strong> <code>integer</code>, required</li><li><strong><code>error</code></strong> <code>string</code>, required</li><li><strong><code>message</code></strong> <code>string</code>, required</li></ul>',70)])])}const h=o(d,[["render",s]]);export{p as __pageData,h as default};
